const EVENTS = [
  { y: 364, mo: 2, t: '瓦伦提尼安即位', p: '尼西亚', m: '今土耳其布尔萨省伊兹尼克', ll: [29.72, 40.43], k: 'pol', refs: ['阿米阿努斯', '吉本·衰亡史'],
    d: '约维安在从东方回君士坦丁堡的路上，死在比提尼亚的一个小驿站里，据说是被新粉刷的房间里炭火的烟气熏死的，在位仅八个月。军官们在尼西亚推举潘诺尼亚出身的禁卫军官瓦伦提尼安为帝。他登上高台准备讲话时，士兵们高喊要他立即再选一位共治皇帝，他举起手说：选谁由我来定。一个月后，他立弟弟瓦伦斯为奥古斯都。',
    who: ['约维安', '瓦伦提尼安一世', '瓦伦斯'] },
  { y: 364, mo: 8, t: '兄弟分治', p: '纳伊苏斯', m: '今塞尔维亚尼什', ll: [21.9, 43.32], k: 'pol', refs: ['阿米阿努斯', '吉本·衰亡史'],
    d: '兄弟二人在奈苏斯附近的一座城郊宫殿里瓜分了军队、官员与行省：瓦伦提尼安统治西方，坐镇米兰与特里尔，防守莱茵河与多瑙河上游；瓦伦斯统治从色雷斯到埃及的东方，以君士坦丁堡为都。此后帝国虽然名义上仍是一个，东西两部却越来越各行其是。瓦伦提尼安性情暴躁，是个精力充沛的军人；瓦伦斯出身行伍，不通希腊语，是一位阿里乌派的基督徒。',
    who: ['瓦伦提尼安一世', '瓦伦斯'] },
  { y: 365, mo: 7, t: '克里特大地震与海啸', p: '亚历山大里亚', m: '今埃及亚历山大', ll: [29.92, 31.2], k: 'eco', refs: ['阿米阿努斯'],
    d: '七月二十一日黎明，地中海东部发生了一场大地震，震中大约在克里特岛西部，岛的西端至今比古代抬高了九米。阿米阿努斯记下了随后的海啸：**海水向后退去，离开了陆地，最深的海底都露了出来，许多海中的动物被留在泥里||The sea was driven backwards, so as to recede from the land, and the very depths were uncovered, so that many marine animals were left sticking in the mud**。人们跑到露出来的海底去捡鱼，海水突然涌回，淹没了沿岸的城市。在亚历山大里亚，有的船被冲到了房顶上，他后来在莫东附近还见过一艘被冲上岸、朽烂在那里的船。',
    who: ['阿米阿努斯·马塞利努斯'] },
  { y: 365, mo: 9, t: '普罗科匹乌斯称帝', p: '君士坦丁堡', m: '今土耳其伊斯坦布尔', ll: [28.98, 41.01], k: 'war', refs: ['阿米阿努斯', '吉本·衰亡史'],
    d: '尤利安的远亲普罗科匹乌斯在尤利安死后一直躲藏着，九月趁瓦伦斯东去，在君士坦丁堡被两个军团拥立为帝。他抱着君士坦提乌斯二世的遗腹女出现在军前，打着君士坦丁家族的旗号，一度控制了色雷斯与比提尼亚，连多瑙河北岸的哥特人也派兵相助。次年五月，他的部下在弗里吉亚的提亚提拉与那科利亚先后倒戈，普罗科匹乌斯被出卖，斩首示众。',
    who: ['普罗科匹乌斯', '瓦伦斯'] },
  { y: 366, mo: 10, t: '达马苏斯与乌尔西努斯', p: '罗马', m: '今意大利罗马', ll: [12.48, 41.89], k: 'cul', refs: ['阿米阿努斯'],
    d: '罗马主教利贝里乌斯死后，达马苏斯与乌尔西努斯两派争夺主教之位，在街头大打出手。阿米阿努斯写道：**可以肯定的是，有一天在西基尼努斯大会堂，一座基督教的教堂里，发现了一百三十七具尸体||It is certain that on one day one hundred and thirty-seven dead bodies were found in the Basilica of Sicininus, which is a Christian church**。他说难怪人们争得这么凶，罗马主教坐着华丽的马车出行，穿着考究，宴席胜过帝王。达马苏斯最后胜出，他后来请秘书哲罗姆修订拉丁文圣经，又用优美的铭文装饰殉道者的墓穴。',
    who: ['达马苏斯', '哲罗姆', '阿米阿努斯·马塞利努斯'] },
  { y: 367, mo: 8, t: '蛮族大阴谋', p: '伦蒂尼乌姆', m: '今英国伦敦', ll: [-0.09, 51.51], k: 'war', refs: ['阿米阿努斯', '吉本·衰亡史'],
    d: '这一年，皮克特人、苏格兰人（来自爱尔兰）与阿塔科蒂人同时袭击不列颠，法兰克人与撒克逊人劫掠高卢沿岸，哈德良长城的守军叛变，不列颠的海岸伯爵战死，阿米阿努斯称之为“蛮族的阴谋”。瓦伦提尼安派老狄奥多西（后来那位皇帝的父亲）渡海平乱，他收复伦迪尼姆，修复城防，两年后肃清了全岛。同年八月，瓦伦提尼安在亚眠立八岁的儿子格拉提安为奥古斯都。',
    who: ['瓦伦提尼安一世', '格拉提安'] },
  { y: 374, mo: 12, t: '安布罗斯当选米兰主教', p: '梅狄奥拉努姆', m: '今意大利米兰', ll: [9.19, 45.46], k: 'cul', refs: ['吉本·衰亡史', '后世文献'],
    d: '米兰的阿里乌派主教死后，正统派与阿里乌派争执不下，行省总督安布罗斯赶到教堂维持秩序。据说人群中有个孩子喊了一声“安布罗斯当主教”，众人随即齐声拥戴。他当时还只是一个慕道者，没有受洗，一周之内受洗、按立，成为米兰主教。安布罗斯出身罗马贵族，精通希腊语，此后二十多年里他是西方最有权势的教士，三位皇帝都对他敬畏有加。',
    who: ['安布罗斯'] },
  { y: 375, mo: 11, t: '瓦伦提尼安一世之死', p: '布里格提奥', m: '今匈牙利科马罗姆附近的瑟尼', ll: [18.18, 47.76], k: 'pol', refs: ['阿米阿努斯', '吉本·衰亡史'],
    d: '夸狄人的国王被罗马将领诱杀，夸狄人与萨尔马提亚人渡河报复。瓦伦提尼安亲征，在多瑙河边的布里格提奥接见夸狄人的使者，听他们辩解说是罗马人先挑衅，勃然大怒，痛斥他们忘恩负义。阿米阿努斯写道：**突然，仿佛被天上的雷击中，他的呼吸和声音停止了，面色发紫||suddenly, as if he had been stricken from heaven, his breathing and his voice ceased, and his countenance appeared bloodshot**，随即血管破裂而死。军队拥立他年仅四岁的幼子为瓦伦提尼安二世，与同父异母的哥哥格拉提安共治西方。',
    who: ['瓦伦提尼安一世', '格拉提安', '瓦伦提尼安二世', '阿米阿努斯·马塞利努斯'] },
  { y: 376, mo: 9, t: '哥特人渡过多瑙河', p: '杜罗斯托鲁姆', m: '今保加利亚锡利斯特拉', ll: [27.26, 44.12], k: 'war', refs: ['阿米阿努斯', '吉本·衰亡史'],
    d: '一个闻所未闻的民族从东方的草原上出现了。阿米阿努斯说：**被称为匈人的民族，古代的记载中只略有提及，他们住在亚速海以外、冰封的大洋边上，野蛮无与伦比||the people called Huns, slightly mentioned in the ancient records, live beyond the Sea of Azov, on the border of the Frozen Ocean, and are a race savage beyond all parallel**。他们骑在马上吃喝睡觉，矮壮粗短，**你会把他们当成两条腿的野兽||so that you might fancy them two-legged beasts**。匈人征服了顿河边的阿兰人，击溃了东哥特人的老王埃尔马纳里克的王国。走投无路的特尔温吉哥特人在弗里提格恩率领下来到多瑙河边，请求入境，瓦伦斯答应了，成千上万的哥特人乘船、木筏与挖空的树干渡过了大河。',
    who: ['弗里提格恩', '瓦伦斯', '阿米阿努斯·马塞利努斯'] },
  { y: 378, mo: 8, t: '阿德里安堡之战', p: '阿德里安堡', m: '今土耳其埃迪尔内', ll: [26.56, 41.68], k: 'war', refs: ['阿米阿努斯', '吉本·衰亡史'],
    d: '罗马官员克扣粮食，逼得饥饿的哥特人用子女换狗肉，哥特人终于起兵，在色雷斯四处劫掠。瓦伦斯不等侄子格拉提安的援军赶到，八月九日在阿德里安堡城外发起进攻，哥特人的骑兵突然从侧翼杀出，罗马步兵挤成一团，无法挥动武器。阿米阿努斯写道：**全军逃出来的不到三分之一||Scarcely one-third of the whole army escaped**，**除了坎尼之战，我们的史册中没有记载过如此惨重的屠杀||Nor, except the battle of Cannae, is so destructive a slaughter recorded in our annals**。瓦伦斯下落不明，**或许死于战斗，或许（人们更相信这一点）在农舍里被活活烧死||he had perished in battle, or else certainly (as is rather believed) burnt to death in the cottage**。阿米阿努斯的《历史》就写到这里为止。',
    who: ['瓦伦斯', '弗里提格恩', '格拉提安', '阿米阿努斯·马塞利努斯'] },
  { y: 379, mo: 1, t: '狄奥多西即位', p: '西尔米乌姆', m: '今塞尔维亚斯雷姆斯卡米特罗维察', ll: [19.61, 44.97], k: 'pol', refs: ['吉本·衰亡史', '后世文献'],
    d: '东方的野战军覆没，十九岁的格拉提安知道自己守不住两边，一月十九日在西尔米乌姆立西班牙出身的将领狄奥多西为东方的奥古斯都，又把东伊利里库姆（马其顿与希腊）划给了他。狄奥多西的父亲老狄奥多西曾平定不列颠与阿非利加，几年前被人诬陷处死，他本人退隐在西班牙的庄园里，被召回后在多瑙河上打了胜仗。他重建军队，大量招募哥特人与其他蛮族入伍。',
    who: ['格拉提安', '狄奥多西'] },
  { y: 379, mo: 8, t: '沙普尔二世病逝', p: '泰西封', m: '今伊拉克巴格达东南', ll: [44.58, 33.09], k: 'pol', refs: ['后世文献'],
    d: '统治萨珊波斯七十年的沙普尔二世病逝。他据说还在母腹中就被立为王，在位期间三次围攻尼西比斯，打退了尤利安，迫使约维安割让了底格里斯河以东的五个地区，又多次干预亚美尼亚。他死后，波斯几代国王在位都不长，与罗马大体保持着和平，双方都把力量转向了北方草原上的威胁。',
    who: ['沙普尔二世'] },
  { y: 380, mo: 2, t: '帖撒罗尼迦敕令', p: '帖撒罗尼迦', m: '今希腊塞萨洛尼基', ll: [22.94, 40.64], k: 'cul', refs: ['吉本·衰亡史'],
    d: '狄奥多西在帖撒罗尼迦病重，由城中的正统派主教施洗。二月二十八日，他与格拉提安、瓦伦提尼安二世联名颁布敕令，要求所有臣民信奉罗马主教达马苏斯与亚历山大里亚主教彼得所传的信仰，即圣父、圣子、圣灵同一神性的三位一体，只有信奉它的人才能称为“大公基督徒”，其余都是异端。这是基督教第一次由皇帝的法令确定为帝国唯一合法的信仰，后世把它当作基督教成为罗马国教的标志。',
    who: ['狄奥多西', '格拉提安', '达马苏斯'] },
  { y: 381, mo: 5, t: '君士坦丁堡会议', p: '君士坦丁堡', m: '今土耳其伊斯坦布尔', ll: [28.98, 41.01], k: 'cul', refs: ['吉本·衰亡史', '后世文献'],
    d: '狄奥多西进入君士坦丁堡后，把阿里乌派的主教赶出了城里的教堂，五月召集东方一百五十位主教开会，史称第二次大公会议。会议重申并扩充了尼西亚信经，确认圣灵与圣父、圣子同受敬拜，这就是今天各大教会仍在诵读的“尼西亚—君士坦丁堡信经”；又规定君士坦丁堡主教的地位仅次于罗马主教，因为这里是“新罗马”。阿里乌派在帝国境内从此衰落，却在已经接受它的哥特人等蛮族中流传了下去。',
    who: ['狄奥多西'] },
  { y: 382, mo: 10, t: '哥特人成为同盟者', p: '诺维', m: '今保加利亚斯维什托夫附近', ll: [25.37, 43.62], k: 'dip', refs: ['吉本·衰亡史', '后世文献'],
    d: '经过四年战争，狄奥多西无法消灭哥特人，只得在十月与他们订约：哥特人作为“同盟者”定居在多瑙河南岸的默西亚与色雷斯，免税耕种，保留自己的首领与法律，战时以本族军队为皇帝作战。这是第一次有一整个蛮族在帝国境内保持着自己的独立。吉本认为，这个条约为日后的灾难埋下了伏笔。同年，曾把圣经译成哥特文的乌尔菲拉仍在为阿里乌派的信仰奔走。',
    who: ['狄奥多西', '乌尔菲拉'] },
  { y: 383, mo: 8, t: '马克西穆斯篡位', p: '卢格杜努姆', m: '今法国里昂', ll: [4.83, 45.76], k: 'war', refs: ['吉本·衰亡史', '后世文献'],
    d: '格拉提安偏爱一支阿兰人卫队，常穿着蛮族的服装与他们一起打猎，引起罗马军人的不满。不列颠的军队拥立西班牙人马格努斯·马克西穆斯为帝，他渡海进入高卢，格拉提安的军队在巴黎附近倒戈。格拉提安带着三百骑兵逃往里昂，八月二十五日被诱杀，年仅二十四岁。马克西穆斯据有不列颠、高卢与西班牙，以特里尔为都，狄奥多西暂时承认了他，只让他不要侵犯瓦伦提尼安二世的意大利。',
    who: ['马克西穆斯', '格拉提安', '瓦伦提尼安二世'] },
  { y: 384, mo: 7, t: '胜利女神祭坛', p: '罗马', m: '今意大利罗马', ll: [12.48, 41.89], k: 'cul', refs: ['吉本·衰亡史'],
    d: '格拉提安在 382 年下令把胜利女神的祭坛搬出元老院，停发维斯塔贞女与祭司的经费。罗马城长官叙马库斯代表仍信奉旧神的元老们上书瓦伦提尼安二世，请求恢复祭坛，他写道：通往如此伟大的奥秘，不可能只有一条道路。米兰主教安布罗斯写信反驳，威胁说皇帝若答应，就不能再进教堂。年轻的皇帝听从了安布罗斯。这是异教与基督教在罗马元老院的最后一次公开交锋。',
    who: ['叙马库斯', '安布罗斯', '瓦伦提尼安二世'] },
  { y: 386, mo: 8, t: '奥古斯丁皈依', p: '梅狄奥拉努姆', m: '今意大利米兰', ll: [9.19, 45.46], k: 'cul', refs: ['奥古斯丁'],
    d: '北非塔加斯特人奥古斯丁经叙马库斯推荐，来米兰任官方的修辞学教授。他年轻时放荡，信过摩尼教，后来又读新柏拉图派的著作，听安布罗斯讲道，内心挣扎。他在《忏悔录》中回忆，少年时曾祈祷说：**赐我贞洁与节制，只是不要现在||Give me chastity and continency, only not yet**。这年夏天，他在米兰的花园里痛哭，**听见邻家有个声音，不知是男孩还是女孩，反复唱着||I heard from a neighbouring house a voice, as of boy or girl, I know not, chanting, and oft repeating**：**拿起来读，拿起来读||Take up and read; Take up and read**。他翻开保罗书信，读到“不可荒宴醉酒”一段，从此决心皈依，次年复活节由安布罗斯施洗。',
    who: ['奥古斯丁', '安布罗斯'] },
  { y: 387, mo: 6, t: '瓜分亚美尼亚', p: '阿尔塔沙特', m: '今亚美尼亚阿拉拉特省', ll: [44.55, 39.96], k: 'dip', refs: ['吉本·衰亡史', '后世文献'],
    d: '亚美尼亚的王位争夺使罗马与波斯一再卷入，狄奥多西终于与波斯王沙普尔三世达成协议，瓜分亚美尼亚：西部较小的一块归罗马，东部大约五分之四归波斯，两边各立一位阿尔沙克家族的国王。几十年后，波斯一侧的亚美尼亚王位被废除，由波斯派总督统治；而亚美尼亚人保留了自己的基督教会，几年后梅斯罗布创制了亚美尼亚字母。',
    who: ['狄奥多西'] },
  { y: 388, mo: 8, t: '马克西穆斯败亡', p: '阿奎莱亚', m: '今意大利弗留利—威尼斯朱利亚大区阿奎莱亚', ll: [13.37, 45.77], k: 'war', refs: ['吉本·衰亡史'],
    d: '387 年马克西穆斯翻越阿尔卑斯山进入意大利，瓦伦提尼安二世与母亲逃往帖撒罗尼迦投奔狄奥多西。狄奥多西娶了瓦伦提尼安的姐姐加拉，次年率军西进，在潘诺尼亚连败马克西穆斯，在阿奎莱亚城中将他擒获。马克西穆斯被押到狄奥多西面前，吉本说，看到昔日骄傲的对手**如今匍匐在他的脚下||now prostrate at his feet**，胜利者不免心生感慨，但士兵们没等他开口就把马克西穆斯拖出去斩首了。',
    who: ['马克西穆斯', '狄奥多西', '瓦伦提尼安二世'] },
  { y: 390, mo: 4, t: '帖撒罗尼迦屠杀', p: '帖撒罗尼迦', m: '今希腊塞萨洛尼基', ll: [22.94, 40.64], k: 'war', refs: ['吉本·衰亡史'],
    d: '帖撒罗尼迦的军队长官、哥特人博忒里克因为囚禁了一位受欢迎的战车御手，被暴动的市民杀死。狄奥多西盛怒之下下令报复，士兵们把市民召进竞技场看比赛，然后关门屠杀。吉本写道：**不分外乡人与本地人、老幼男女、有罪无罪的屠杀持续了三个小时||The promiscuous carnage continued three hours, without discrimination of strangers or natives, of age or sex, of innocence or guilt**，最保守的估计死了七千人。安布罗斯写信给皇帝，拒绝在他面前举行圣餐，要他公开忏悔。狄奥多西脱下皇袍，在米兰的教堂里当众认罪，**大约八个月之后||After a delay of about eight months**才被重新接纳。',
    who: ['狄奥多西', '安布罗斯'] },
  { y: 391, mo: 6, t: '塞拉皮斯神庙被毁', p: '亚历山大里亚', m: '今埃及亚历山大', ll: [29.92, 31.2], k: 'cul', refs: ['吉本·衰亡史'],
    d: '狄奥多西接连颁布法令，禁止一切献祭，关闭神庙，连在家中焚香敬拜家神也要受罚。在亚历山大里亚，主教提奥菲卢斯带领基督徒攻占了宏伟的塞拉皮斯神庙，一个士兵用斧头劈开了巨大的神像，人们原以为天地会因此崩塌，结果什么也没有发生，只有一群老鼠从神像的头里跑了出来。吉本说，在遍地的废墟中，**人们可以辨认出亚历山大里亚塞拉皮斯神庙的残迹||the spectator may distinguish the ruins of the temple of Serapis, at Alexandria**。393 年，奥林匹亚的运动会也举行了最后一届。',
    who: ['狄奥多西'] },
  { y: 392, mo: 5, t: '瓦伦提尼安二世暴卒', p: '维埃纳', m: '今法国伊泽尔省维埃纳', ll: [4.87, 45.52], k: 'pol', refs: ['吉本·衰亡史', '后世文献'],
    d: '狄奥多西把西部交还瓦伦提尼安二世，派法兰克人将领阿博加斯特辅佐他。二十一岁的皇帝住在维埃纳，被阿博加斯特架空，两人当众争吵，皇帝亲手递给他免职的诏书，阿博加斯特把诏书撕碎扔在地上。五月十五日，人们发现瓦伦提尼安吊死在宫中，是自杀还是被害，至今说不清。阿博加斯特是蛮族，不能自己称帝，八月他拥立宫廷的修辞学教师尤吉尼乌斯为西部皇帝，元老院中的异教徒随即重新竖起了胜利女神的祭坛。',
    who: ['瓦伦提尼安二世', '阿博加斯特', '尤吉尼乌斯'] },
  { y: 394, mo: 9, t: '冷河之战', p: '弗里吉都斯河', m: '今斯洛文尼亚维帕瓦河', ll: [13.85, 45.87], k: 'war', refs: ['吉本·衰亡史'],
    d: '狄奥多西率领东部军队与两万哥特同盟军西进，九月走出朱利安阿尔卑斯山时，**看见高卢人与日耳曼人的营帐布满了一直延伸到阿奎莱亚城下与弗里吉都斯河岸边的平原||the open country which extends to the walls of Aquileia, and the banks of the Frigidus**（吉本语），弗里吉都斯意为“冷河”。第一天，冲在前面的哥特人死伤过半。第二天，一阵猛烈的北风迎面刮向西军，把他们的箭矛吹回自己阵中，基督徒说这是上帝在帮助狄奥多西。尤吉尼乌斯被俘斩首，阿博加斯特在山中逃了两天后自杀。在这一战中为狄奥多西流血的哥特人当中，有一个年轻的首领，名叫阿拉里克。',
    who: ['狄奥多西', '尤吉尼乌斯', '阿博加斯特', '阿拉里克', '斯提里科'] },
  { y: 395, mo: 1, t: '狄奥多西之死与帝国分治', p: '梅狄奥拉努姆', m: '今意大利米兰', ll: [9.19, 45.46], k: 'pol', refs: ['吉本·衰亡史'],
    d: '狄奥多西在米兰病逝，享年四十八岁，他是最后一位统治整个罗马帝国的皇帝。十七岁的长子阿卡狄乌斯统治东部，十岁的次子霍诺留统治西部，两人都由大臣把持。西部的实权在汪达尔人后裔、娶了狄奥多西侄女的大将斯提里科手中。吉本写道：**罗马的天才与狄奥多西一同死去||The genius of Rome expired with Theodosius**。帝国从此分为东西两部，再也没有在一位皇帝之下统一过。',
    who: ['狄奥多西', '阿卡狄乌斯', '霍诺留', '斯提里科', '安布罗斯'] },
  { y: 396, mo: 6, t: '阿拉里克蹂躏希腊', p: '科林斯', m: '今希腊科林西亚州', ll: [22.88, 37.91], k: 'war', refs: ['吉本·衰亡史'],
    d: '狄奥多西死后，哥特同盟军拥立巴尔特家族的阿拉里克为王，起兵要求更高的军饷与官职。他们沿着温泉关进入希腊，没有遇到抵抗，雅典交出财物得以保全，科林斯、阿尔戈斯与斯巴达被洗劫，埃莱夫西斯的秘仪神庙从此荒废。斯提里科从海上赶来，在伯罗奔尼撒围住了哥特人，却又放他们走了，据说是东部宫廷不愿西部的将军插手。不久阿卡狄乌斯反而任命阿拉里克为伊利里库姆的军队长官。',
    who: ['阿拉里克', '斯提里科', '阿卡狄乌斯'] },
  { y: 397, mo: 9, t: '安布罗斯与马丁', p: '图罗尼', m: '今法国图尔', ll: [0.69, 47.39], k: 'cul', refs: ['后世文献'],
    d: '这一年春天安布罗斯在米兰去世，秋天图尔主教马丁也去世了。马丁原是潘诺尼亚出身的士兵，传说他在亚眠城门把自己的斗篷割下一半给了一个乞丐，夜里梦见基督穿着那半件斗篷。他在利居热建立了高卢第一座修道院，在乡间捣毁神庙，劝化农民。他的传记由苏尔皮基乌斯·塞维鲁写成，流传极广，他后来成为法兰克人最敬奉的圣徒。',
    who: ['图尔的马丁', '安布罗斯'] },
  { y: 401, mo: 11, t: '阿拉里克进入意大利', p: '阿奎莱亚', m: '今意大利弗留利—威尼斯朱利亚大区阿奎莱亚', ll: [13.37, 45.77], k: 'war', refs: ['吉本·衰亡史'],
    d: '东部宫廷不再供养哥特人，阿拉里克率部离开伊利里库姆，十一月越过朱利安阿尔卑斯山进入意大利，围攻阿奎莱亚，兵临米兰。斯提里科从雷蒂亚召回军队，又调来不列颠与莱茵河的守军，西部边防因此空虚。霍诺留的宫廷惊恐万状，有人主张把朝廷迁到高卢。',
    who: ['阿拉里克', '斯提里科', '霍诺留'] },
  { y: 402, mo: 4, t: '波伦提亚之战与迁都拉文纳', p: '拉文纳', m: '今意大利拉文纳', ll: [12.2, 44.42], k: 'war', refs: ['吉本·衰亡史'],
    d: '复活节那天，斯提里科在皮埃蒙特的波伦提亚突袭了哥特人的营地，俘获了阿拉里克的妻儿与大批财宝，阿拉里克被迫退出意大利。经过这次惊吓，霍诺留把宫廷从米兰迁到亚得里亚海边的拉文纳。吉本描写这座城：运河把城市分成许多小岛，靠船与桥往来，**拉文纳的房屋，外观可比威尼斯，建在木桩之上||the houses of Ravenna, whose appearance may be compared to that of Venice, were raised on the foundation of wooden piles**，四周是大片的沼泽，只有一条堤道与陆地相连。此后七十多年，拉文纳一直是西罗马帝国的都城。',
    who: ['斯提里科', '阿拉里克', '霍诺留'] },
  { y: 404, mo: 1, t: '忒勒马科斯与角斗', p: '罗马', m: '今意大利罗马', ll: [12.48, 41.89], k: 'cul', refs: ['吉本·衰亡史'],
    d: '霍诺留在罗马举行凯旋式，庆祝打败哥特人，照例举办了角斗表演。据说一个来自东方的修士忒勒马科斯跳进竞技场，想把角斗士分开，被愤怒的观众用石头砸死。吉本说他**死得比活着更有益于人类||whose death was more useful to mankind than his life**，因为霍诺留随后下令永远废除角斗。罗马竞技场里人与人的搏杀就此结束，猎杀野兽的表演又延续了一百多年。',
    who: ['忒勒马科斯', '霍诺留'] },
  { y: 404, mo: 6, t: '金口约翰被流放', p: '君士坦丁堡', m: '今土耳其伊斯坦布尔', ll: [28.98, 41.01], k: 'cul', refs: ['吉本·衰亡史'],
    d: '安条克的教士约翰以讲道雄辩闻名，被称为“金口”，398 年被召为君士坦丁堡主教。他在讲坛上抨击贵族与宫廷的奢侈，据说把皇后欧多克西娅比作要人头的希罗底，又整顿腐败的教士，得罪了许多人。403 年亚历山大里亚主教提奥菲卢斯在卡尔西顿附近的橡树庄召开会议，将他革职，民众的抗议与一场地震使他很快被召回。次年六月他再次被流放，追随者在混乱中烧毁了圣索菲亚大教堂与元老院。他在流放地仍不断写信，407 年在被押往更远处的路上死去。',
    who: ['约翰·克里索斯托', '阿卡狄乌斯'] },
  { y: 406, mo: 8, t: '费苏莱之战', p: '费苏莱', m: '今意大利佛罗伦萨附近菲耶索莱', ll: [11.29, 43.81], k: 'war', refs: ['吉本·衰亡史'],
    d: '405 年，一个叫拉达盖苏斯的哥特首领带着大批异教的哥特人与其他部族，从多瑙河中游翻越阿尔卑斯山闯入意大利，一直打到佛罗伦萨城下。斯提里科集结了三十个军团与匈人、阿兰人的雇佣军，把他们围困在费苏莱的山上，饥渴迫使敌人投降。八月拉达盖苏斯被斩首，大批俘虏被贱卖为奴，据说一个奴隶只值一枚金币。',
    who: ['斯提里科'] },
  { y: 406, mo: 12, t: '渡过莱茵河', p: '莫贡提亚库姆', m: '今德国美因茨', ll: [8.27, 50.0], k: 'war', refs: ['吉本·衰亡史'],
    d: '汪达尔人、阿兰人与苏维汇人在莱茵河东岸集结，击败了为罗马守边的法兰克人。吉本写道：**在一年的最后一天，莱茵河很可能已经封冻，他们没有遇到抵抗，就进入了毫无防备的高卢诸省||on the last day of the year, in a season when the waters of the Rhine were most probably frozen, they entered, without opposition, the defenceless provinces of Gaul**。美因茨被攻破，沃尔姆斯、兰斯、亚眠、阿拉斯、图尔奈相继遭劫，吉本认为这次渡河可以看作罗马帝国在阿尔卑斯山以北的灭亡，因为这些民族再也没有退回去。',
    who: ['斯提里科'] },
  { y: 408, mo: 5, t: '阿卡狄乌斯病逝', p: '君士坦丁堡', m: '今土耳其伊斯坦布尔', ll: [28.98, 41.01], k: 'pol', refs: ['吉本·衰亡史'],
    d: '东部皇帝阿卡狄乌斯病逝，年仅三十一岁，由七岁的儿子狄奥多西二世继位。阿卡狄乌斯在位十三年，朝政先后被宦官欧特罗皮乌斯与皇后欧多克西娅把持，敢于批评宫廷奢侈的君士坦丁堡主教“金口”约翰被两次流放，死在黑海边的路上。东部的大臣安特米乌斯摄政，几年后开始修建保护君士坦丁堡的陆墙。',
    who: ['阿卡狄乌斯', '狄奥多西二世', '约翰·克里索斯托'], post: ['约翰·克里索斯托'] },
  { y: 408, mo: 8, t: '斯提里科被杀', p: '拉文纳', m: '今意大利拉文纳', ll: [12.2, 44.42], k: 'pol', refs: ['吉本·衰亡史'],
    d: '这时不列颠的军队又拥立了一位君士坦丁三世，他渡海占领了高卢与西班牙，斯提里科却在与阿拉里克谈判，主张付给哥特人四千磅黄金。宫廷里的政敌告诉霍诺留，斯提里科想让自己的儿子当东部皇帝。帕维亚的军队哗变，屠杀了斯提里科的亲信，斯提里科逃进拉文纳的教堂，八月二十二日走出教堂时被斩首，他禁止身边的蛮族卫兵为他抵抗。随后意大利各城的罗马人屠杀了驻军中蛮族士兵的家眷，三万名蛮族士兵投奔了阿拉里克。',
    who: ['斯提里科', '霍诺留', '阿拉里克'] },
  { y: 409, mo: 10, t: '蛮族进入西班牙', p: '比利牛斯山', m: '今法国与西班牙边境', ll: [-1.3, 43.0], k: 'war', refs: ['吉本·衰亡史', '后世文献'],
    d: '在高卢劫掠了将近三年之后，汪达尔人、阿兰人与苏维汇人在九月底或十月越过比利牛斯山的关口，进入西班牙。守关的军队是篡位者君士坦丁三世派去的，据说他们放蛮族过了关，自己也加入了劫掠。编年史家伊达提乌斯描写随后的西班牙：刀兵、饥荒、瘟疫与野兽四种灾祸一齐降临，饥饿的人们甚至吃人肉。',
    who: ['霍诺留'] },
  { y: 410, mo: 6, t: '霍诺留致书不列颠', p: '伦蒂尼乌姆', m: '今英国伦敦', ll: [-0.09, 51.51], k: 'pol', refs: ['吉本·衰亡史', '后世文献'],
    d: '不列颠的军队几年间接连拥立了三个皇帝，最后一个君士坦丁三世把剩下的军队都带去了高卢。撒克逊人从海上来袭，不列颠的城市自己赶走了君士坦丁的官员，组织起来抵抗。据佐西莫斯记载，霍诺留写信给不列颠诸城，让它们自行防卫。罗马对不列颠近四百年的统治就此结束，此后再也没有罗马的军队与官员渡海回来。',
    who: ['霍诺留'] },
  { y: 410, mo: 8, t: '阿拉里克洗劫罗马', p: '罗马', m: '今意大利罗马', ll: [12.48, 41.89], k: 'war', refs: ['吉本·衰亡史', '奥古斯丁'],
    d: '阿拉里克两次围困罗马，勒索了大批黄金、白银、丝绸与胡椒，又扶立元老阿塔卢斯为傀儡皇帝，躲在拉文纳的霍诺留始终拒绝给他土地与官职。八月二十四日，**午夜时分，萨拉里亚门悄悄打开，居民们被哥特人号角的巨响惊醒||At the hour of midnight, the Salarian gate was silently opened, and the inhabitants were awakened by the tremendous sound of the Gothic trumpet**（吉本语）。哥特人在城里劫掠了三天，信奉阿里乌派的他们没有动使徒的教堂。罗马城八百年来第一次落入外敌之手，在伯利恒的哲罗姆听到消息后写道：征服了整个世界的城市，自己被征服了。阿拉里克带走了狄奥多西的女儿加拉·普拉西提阿做人质。',
    who: ['阿拉里克', '霍诺留', '加拉·普拉西提阿', '哲罗姆'] },
  { y: 410, mo: 12, t: '阿拉里克之死', p: '孔森提亚', m: '今意大利卡拉布里亚大区科森扎', ll: [16.25, 39.3], k: 'war', refs: ['吉本·衰亡史'],
    d: '阿拉里克率军南下，想渡海去西西里与阿非利加，船只被风暴摧毁，不久他在科森扎病死，年约四十岁。吉本描写哥特人为他举行的葬礼：**他们强迫一大群俘虏，把流经孔森提亚城下的小河布森提努斯改道||they forcibly diverted the course of the Busentinus, a small river that washes the walls of Consentia**，在河床上修建了王陵，放进从罗马掠来的珍宝，再让河水流回原道，修墓的俘虏全被杀死，以免泄露墓的位置。他的妻弟阿陶尔夫继承了王位，带着哥特人北上进入高卢。',
    who: ['阿拉里克', '阿陶尔夫'] },
  { y: 411, mo: 9, t: '瓜分西班牙', p: '埃梅里塔', m: '今西班牙梅里达', ll: [-6.34, 38.92], k: 'war', refs: ['后世文献'],
    d: '蛮族们在西班牙劫掠了两年之后，按伊达提乌斯的说法，用抽签的办法瓜分了这片土地：哈斯丁汪达尔人与苏维汇人分得西北的加利西亚，阿兰人分得卢西塔尼亚与迦太基省，西林汪达尔人分得南方的贝提卡。这一年，霍诺留的将军君士坦提乌斯在阿尔勒打败了篡位者君士坦丁三世，把他押往意大利处死。',
    who: ['霍诺留'] },
  { y: 415, mo: 3, t: '希帕提娅之死', p: '亚历山大里亚', m: '今埃及亚历山大', ll: [29.92, 31.2], k: 'cul', refs: ['吉本·衰亡史'],
    d: '亚历山大里亚的希帕提娅是数学家塞翁的女儿，注释过阿波罗尼奥斯与丢番图的数学著作，公开讲授柏拉图与亚里士多德的哲学，学生中有基督徒也有异教徒。主教西里尔与埃及总督奥瑞斯特斯不和，有传言说希帕提娅是两人和解的唯一障碍。三月大斋期间，吉本写道：**希帕提娅被从马车上拖下来，剥去衣服，拖进教堂，被读经员彼得与一群野蛮残忍的狂热分子残杀||Hypatia was torn from her chariot, stripped naked, dragged to the church, and inhumanly butchered by the hands of Peter the reader, and a troop of savage and merciless fanatics**，她的遗体被投入火中。',
    who: ['希帕提娅', '西里尔'] },
  { y: 418, mo: 6, t: '西哥特人定居阿基坦', p: '托洛萨', m: '今法国图卢兹', ll: [1.44, 43.6], k: 'pol', refs: ['吉本·衰亡史', '约达尼斯'],
    d: '阿陶尔夫在纳博讷娶了加拉·普拉西提阿，婚礼按罗马的礼仪举行，他据说曾说过，想用哥特人的力量来恢复罗马的威名。阿陶尔夫在巴塞罗那遇刺后，新王瓦利亚把普拉西提阿送还霍诺留，换取了六十万斗粮食，并替罗马出兵西班牙，几乎消灭了西林汪达尔人与阿兰人。418 年，罗马把从图卢兹到大西洋岸的阿基坦第二行省交给西哥特人定居，以图卢兹为王都，这是在罗马帝国境内建立的第一个蛮族王国。普拉西提阿回到拉文纳后嫁给了将军君士坦提乌斯，生下了瓦伦提尼安三世。',
    who: ['瓦利亚', '加拉·普拉西提阿', '霍诺留', '阿陶尔夫'], post: ['阿陶尔夫'] },
  { y: 423, mo: 8, t: '霍诺留病逝', p: '拉文纳', m: '今意大利拉文纳', ll: [12.2, 44.42], k: 'pol', refs: ['吉本·衰亡史', '后世文献'],
    d: '霍诺留在拉文纳病逝，在位二十八年，他统治的年代里不列颠丢失，罗马被洗劫，蛮族在高卢与西班牙扎下了根。据普罗科匹乌斯讲的一个故事，罗马陷落的消息传来时，他以为是自己养的一只名叫“罗马”的鸡死了，听说只是城市陷落，才松了一口气。他死后，宫廷书记官约翰在拉文纳称帝，他的妹妹普拉西提阿正带着幼子流亡在君士坦丁堡。',
    who: ['霍诺留', '加拉·普拉西提阿'] },
  { y: 425, mo: 10, t: '瓦伦提尼安三世即位', p: '罗马', m: '今意大利罗马', ll: [12.48, 41.89], k: 'pol', refs: ['吉本·衰亡史'],
    d: '东部的狄奥多西二世派兵攻下拉文纳，处死篡位者约翰，十月二十三日在罗马立普拉西提阿六岁的儿子为西部皇帝瓦伦提尼安三世，由普拉西提阿摄政。约翰的部将埃提乌斯带着从匈人那里借来的六万大军赶到时已晚了三天，他与普拉西提阿讲和，被派往高卢掌兵。埃提乌斯年轻时在阿拉里克与匈人那里都做过人质，与匈人交情很深。',
    who: ['瓦伦提尼安三世', '加拉·普拉西提阿', '狄奥多西二世', '埃提乌斯'] },
  { y: 429, mo: 5, t: '汪达尔人渡海', p: '尤利亚·特拉杜克塔', m: '今西班牙塔里法附近', ll: [-5.6, 36.01], k: 'war', refs: ['吉本·衰亡史', '后世文献'],
    d: '汪达尔人在西班牙南部重新强大起来，又吸收了残余的阿兰人。新王盖萨里克是个跛子，吉本说他城府很深，寡言少语。428 年他继位后，五月带着全族八万人从直布罗陀海峡附近渡海进入阿非利加。据说是阿非利加的罗马将军卜尼法斯与宫廷反目，请他们来的，吉本把卜尼法斯与埃提乌斯并称，说他们**配得上“最后的罗马人”之名||who may be deservedly named as the last of the Romans**，而他们的不和直接导致了阿非利加的丧失。',
    who: ['盖萨里克', '卜尼法斯', '埃提乌斯'] },
  { y: 430, mo: 8, t: '奥古斯丁之死', p: '希波', m: '今阿尔及利亚安纳巴', ll: [7.76, 36.9], k: 'cul', refs: ['奥古斯丁', '吉本·衰亡史'],
    d: '汪达尔人围攻希波城的第三个月，七十五岁的主教奥古斯丁在城中病逝。罗马被洗劫后，异教徒说这是抛弃旧神的报应，他用十三年时间写成二十二卷的《上帝之城》回应，书中说，人类分属**两座城：上帝之城与世人之城||these two cities--the city of God, and the city of the world**，世上的帝国兴衰无常，信徒真正的家园在天上。他关于原罪、恩典与预定的学说，塑造了此后一千多年的西方神学。希波陷落后，他的藏书幸存了下来。',
    who: ['奥古斯丁', '盖萨里克'] },
  { y: 431, mo: 6, t: '以弗所会议', p: '以弗所', m: '今土耳其伊兹密尔省塞尔丘克', ll: [27.34, 37.94], k: 'cul', refs: ['吉本·衰亡史', '后世文献'],
    d: '君士坦丁堡主教聂斯脱利反对把马利亚称为“神之母”，主张称“基督之母”，以区分基督的神性与人性。亚历山大里亚主教西里尔指责他把基督分成两个位格。狄奥多西二世召集的会议在以弗所举行，西里尔不等聂斯脱利的支持者到场就开会，宣布聂斯脱利为异端，以弗所的民众举着火把欢呼“神之母”。聂斯脱利被流放到埃及，他的追随者东迁波斯，后来一直传到中国，唐朝称之为景教。',
    who: ['聂斯脱利', '西里尔', '狄奥多西二世'] },
  { y: 432, mo: 6, t: '帕特里克到爱尔兰', p: '阿尔马', m: '今北爱尔兰阿马', ll: [-6.65, 54.35], k: 'cul', refs: ['后世文献'],
    d: '据传统的说法，帕特里克这一年回到爱尔兰传教。他是不列颠一个罗马化家庭的儿子，十六岁时被爱尔兰海盗掳去放羊六年，逃回家乡后做了教士，梦见爱尔兰人呼唤他回去。他在《忏悔》中自称是“一个罪人，最粗鄙的乡下人”。爱尔兰从未被罗马统治过，后来却成为拉丁文化的避难所，它的修道院保存了大量古典典籍。',
    who: ['帕特里克'] },
  { y: 433, mo: 6, t: '埃提乌斯借匈人之力', p: '阿昆库姆', m: '今匈牙利布达佩斯', ll: [19.04, 47.56], k: 'pol', refs: ['吉本·衰亡史', '后世文献'],
    d: '埃提乌斯与卜尼法斯在意大利交战，卜尼法斯获胜后伤重而死，埃提乌斯逃到匈人那里，带着匈人的军队回来，迫使普拉西提阿任命他为西部的最高统帅。此后二十年间，埃提乌斯是西罗马帝国的真正主人。作为回报，匈人得到了潘诺尼亚的一部分，他们的王庭设在多瑙河与蒂萨河之间的平原上。',
    who: ['埃提乌斯', '卜尼法斯', '加拉·普拉西提阿'], post: ['卜尼法斯'] },
  { y: 434, mo: 6, t: '阿提拉与布列达', p: '蒂萨河', m: '今匈牙利大平原', ll: [20.2, 46.9], k: 'pol', refs: ['约达尼斯', '吉本·衰亡史'],
    d: '匈人王卢阿死后，侄子阿提拉与哥哥布列达共同继位，445 年阿提拉杀死布列达，独掌大权，他统治的部族从莱茵河一直到黑海北岸。约达尼斯说他是**一个生来要震撼诸民族的人，万国之鞭||He was a man born into the world to shake the nations, the scourge of all lands**，又据普里斯库斯描写他的相貌：**身材矮小，胸膛宽阔，头很大，眼睛小，胡须稀疏而夹着灰白，鼻子扁平，皮肤黝黑||He was short of stature with a broad chest and a large head; his eyes were small, his beard thin and sprinkled with gray; and he had a flat nose and a swarthy complexion**。后世基督徒称他为“上帝之鞭”，吉本说，若论杀戮之烈，**鞑靼人帖木儿与匈人阿提拉都配得上“上帝之鞭”这个称号||either the Tartar or the Hun might deserve the epithet of the Scourge of God**。',
    who: ['阿提拉'] },
  { y: 436, mo: 9, t: '勃艮第王国覆灭', p: '沃尔姆斯', m: '今德国莱茵兰—普法尔茨州沃尔姆斯', ll: [8.36, 49.63], k: 'war', refs: ['后世文献'],
    d: '勃艮第人在莱茵河中游建立了以沃尔姆斯为中心的王国，他们越界侵入比利时高卢，埃提乌斯召来匈人雇佣军讨伐，国王贡第卡留斯与约两万勃艮第人被杀。这场灾难在日耳曼人中口耳相传了几百年，到十三世纪写成了史诗《尼伯龙根之歌》，诗中的国王巩特尔就是贡第卡留斯，匈人王埃策尔就是阿提拉。',
    who: ['埃提乌斯'] },
  { y: 438, mo: 2, t: '狄奥多西法典', p: '君士坦丁堡', m: '今土耳其伊斯坦布尔', ll: [28.98, 41.01], k: 'cul', refs: ['吉本·衰亡史'],
    d: '狄奥多西二世命法学家把君士坦丁以来历代皇帝颁布的法令汇编成十六卷，二月十五日在东部颁行，次年在西部的元老院宣读后生效，这就是《狄奥多西法典》。它是第一部由皇帝下令编纂的官方法典，最后一卷专收关于宗教的法令。西部的蛮族王国后来也据此编写了给罗马臣民用的法典，它比查士丁尼的法典早了将近一百年。',
    who: ['狄奥多西二世'] },
  { y: 439, mo: 10, t: '汪达尔人攻占迦太基', p: '迦太基', m: '今突尼斯突尼斯市附近', ll: [10.32, 36.85], k: 'war', refs: ['吉本·衰亡史'],
    d: '435 年罗马承认汪达尔人占有努米底亚，四年后，盖萨里克撕毁和约，十月十九日突袭了阿非利加的首府迦太基，没有遇到什么抵抗。吉本说他下令所有居民交出金银珠宝，隐藏财产的以叛国论处。阿非利加是西罗马帝国最富庶的行省，罗马城的粮食大半来自这里，它的丧失使西部帝国失去了最大的财源。汪达尔人缴获了迦太基港内的船只，从此成为地中海上的海盗。',
    who: ['盖萨里克'] },
  { y: 441, mo: 9, t: '苏维汇人攻占希斯帕利斯', p: '希斯帕利斯', m: '今西班牙塞维利亚', ll: [-5.99, 37.39], k: 'war', refs: ['后世文献'],
    d: '汪达尔人离开西班牙后，西北的苏维汇人乘虚南下，国王雷齐拉先在 439 年占领了卢西塔尼亚的首府梅里达，又在 441 年攻占了贝提卡的首府塞维利亚，西班牙的南部与西部都落入了苏维汇人手中，罗马只剩下东北的塔拉科行省。',
    who: ['雷齐拉'] },
  { y: 443, mo: 6, t: '勃艮第人迁往萨保迪亚', p: '日内瓦', m: '今瑞士日内瓦', ll: [6.14, 46.2], k: 'pol', refs: ['后世文献'],
    d: '埃提乌斯把劫后余生的勃艮第人安置在日内瓦湖周围的萨保迪亚，“萨伏依”这个地名就来自这里，让他们与罗马的地主分享土地，替罗马守卫阿尔卑斯山的通道。勃艮第人后来沿罗讷河向南扩张到里昂，“勃艮第”成为法国东部一个地区的名字。',
    who: ['埃提乌斯'] },
  { y: 446, mo: 6, t: '不列颠人的哀诉', p: '伦蒂尼乌姆', m: '今英国伦敦', ll: [-0.09, 51.51], k: 'war', refs: ['后世文献', '吉本·衰亡史'],
    d: '据六世纪的不列颠修士吉尔达斯记载，不列颠人在皮克特人与苏格兰人的侵扰下，写信向第三次任执政官的埃提乌斯求救：“蛮族把我们赶到海边，大海又把我们推回蛮族那里，我们不是被杀，就是被淹死。”埃提乌斯正忙于高卢的战事，没有回应。吉本称这封信为“不列颠人的呻吟”。',
    who: ['埃提乌斯'] },
  { y: 447, mo: 3, t: '阿提拉与君士坦丁堡城墙', p: '君士坦丁堡', m: '今土耳其伊斯坦布尔', ll: [28.98, 41.01], k: 'war', refs: ['吉本·衰亡史', '后世文献'],
    d: '一月，一场大地震震塌了君士坦丁堡陆墙的一大段，五十七座塔楼倒塌，此时阿提拉正率领匈人南下巴尔干。城中的竞技党派出了一万六千名市民日夜抢修，据城门上的铭文记载，两个月就修好了，外面还加了一道新墙与壕沟，这就是此后一千年里屡次挡住敌人的狄奥多西城墙。阿提拉没有攻城，转而蹂躏了色雷斯与伊利里库姆的七十座城市，迫使东罗马赔款六千磅黄金，每年纳贡两千一百磅。',
    who: ['阿提拉', '狄奥多西二世'] },
  { y: 449, mo: 5, t: '普里斯库斯出使匈人', p: '蒂萨河', m: '今匈牙利大平原', ll: [20.2, 46.9], k: 'dip', refs: ['吉本·衰亡史', '约达尼斯'],
    d: '东罗马派使节到阿提拉的王庭，随行的历史学家普里斯库斯留下了关于匈人最生动的记录。阿提拉住在多瑙河北岸平原上的木头宫殿里，宴会上客人们用金银杯盘，他自己用木杯木盘，穿着朴素。普里斯库斯在那里遇到一个被俘后留下来的希腊商人，他说在匈人中生活比在罗马受税吏的盘剥更自在。原来使团中有人受宦官克里萨菲乌斯指使，想收买阿提拉的亲信刺杀他。吉本注意到，接待使团的两个人，一个是潘诺尼亚人欧瑞斯特斯，一个是日耳曼人埃德科，**阿提拉的这两个仆人，后来成了西部最后一位罗马皇帝与第一位意大利蛮族国王的父亲||the two servants of Attila became the fathers of the last Roman emperor of the West, and of the first Barbarian king of Italy**。',
    who: ['普里斯库斯', '阿提拉', '狄奥多西二世'] },
  { y: 449, mo: 8, t: '亨吉斯特与霍萨', p: '萨尼特岛', m: '今英国肯特郡', ll: [1.35, 51.35], k: 'war', refs: ['吉本·衰亡史', '后世文献'],
    d: '据比德与《盎格鲁—撒克逊编年史》的传统说法，不列颠的统治者沃蒂根请来日耳曼人对付北方的皮克特人。吉本写道：**亨吉斯特与霍萨带着三条船沿东海岸游弋，受丰厚报酬的许诺，答应为不列颠防守||Hengist and Horsa, as they ranged along the Eastern coast with three ships, were engaged, by the promise of an ample stipend, to embrace the defence of Britain**。他们在肯特的萨尼特岛落脚，后来却与雇主反目，招来更多的撒克逊人、盎格鲁人与朱特人，在不列颠东部建立了自己的王国。',
    who: ['亨吉斯特'] },
  { y: 450, mo: 7, t: '狄奥多西二世坠马', p: '君士坦丁堡', m: '今土耳其伊斯坦布尔', ll: [28.98, 41.01], k: 'pol', refs: ['吉本·衰亡史'],
    d: '在位四十二年的狄奥多西二世打猎时从马上摔下，伤重不治。他的姐姐普尔喀丽娅十六岁起就被尊为奥古斯塔，长期主持朝政，她立刻处死了宦官克里萨菲乌斯，嫁给年近六十的将军马尔西安，名义上保持着她的贞洁誓言，让他做了皇帝。马尔西安拒绝再向阿提拉纳贡，说：我有给朋友的黄金，也有给敌人的铁。同年，西部的普拉西提阿去世，她的女儿霍诺利娅为了逃避婚事，送信与戒指给阿提拉求救，阿提拉以此为借口，要求娶她并分得西部帝国的一半作为嫁妆。',
    who: ['狄奥多西二世', '普尔喀丽娅', '马尔西安', '阿提拉', '加拉·普拉西提阿'] },
  { y: 451, mo: 6, t: '卡塔劳尼平原之战', p: '卡塔劳尼', m: '今法国马恩河畔沙隆附近', ll: [4.36, 48.96], k: 'war', refs: ['约达尼斯', '吉本·衰亡史'],
    d: '阿提拉率领匈人、东哥特人、格皮德人等大军渡过莱茵河，攻破梅斯，围攻奥尔良。埃提乌斯说服了西哥特王狄奥多里克一世联手，又召集法兰克人、勃艮第人、阿兰人与阿莫里卡人，解了奥尔良之围，在卡塔劳尼平原迎战。约达尼斯写道：**战场是一片平原，一道陡坡升向一条山脊，双方都想抢占它||The battle field was a plain rising by a sharp slope to a ridge, which both armies sought to gain**。老王狄奥多里克战死，西哥特人在他的儿子率领下奋勇冲杀，阿提拉退回用车辆围成的营地，堆起马鞍准备自焚。埃提乌斯没有乘胜追击，让阿提拉撤回了多瑙河。这是欧洲历史上最著名的战役之一。',
    who: ['埃提乌斯', '阿提拉', '狄奥多里克一世'] },
  { y: 451, mo: 10, t: '卡尔西顿会议', p: '卡尔西顿', m: '今土耳其伊斯坦布尔卡德柯伊', ll: [29.03, 40.99], k: 'cul', refs: ['吉本·衰亡史', '后世文献'],
    d: '马尔西安与普尔喀丽娅在君士坦丁堡对岸的卡尔西顿召集了第四次大公会议，五六百位主教到会。罗马教宗利奥一世送来一封论基督本性的书信，与会者高呼“彼得借利奥之口说话”。会议宣布基督具有完全的神性与完全的人性，“二性”在一个位格中不相混合、不相分离。埃及与叙利亚的许多教会拒绝接受，坚持“一性论”，东方教会从此分裂，今天的科普特教会与亚美尼亚教会都源于这次分裂。',
    who: ['马尔西安', '普尔喀丽娅', '教宗利奥'] },
  { y: 452, mo: 7, t: '阿提拉入侵意大利', p: '明乔河', m: '今意大利曼托瓦附近', ll: [10.72, 45.25], k: 'war', refs: ['约达尼斯', '吉本·衰亡史'],
    d: '阿提拉越过朱利安阿尔卑斯山，攻陷并夷平了阿奎莱亚，米兰与帕维亚相继失守，据说阿奎莱亚的难民逃到了亚得里亚海的潟湖小岛上，后来那里成为威尼斯。教宗利奥一世与两位元老在明乔河边见到阿提拉，劝他退兵。约达尼斯说：**阿提拉一心想去罗马，但据史家普里斯库斯说，他的部下劝住了他，不是出于对这座敌视他们的城市的尊重，而是因为他们记得阿拉里克的下场||Attila\'s mind had been bent on going to Rome. But his followers, as the historian Priscus relates, took him away, not out of regard for the city to which they were hostile, but because they remembered the case of Alaric**，阿拉里克攻下罗马后不久就死了。加上意大利正闹饥荒与瘟疫，东罗马的军队又在多瑙河边进攻匈人的老家，阿提拉退回了潘诺尼亚。',
    who: ['阿提拉', '教宗利奥', '普里斯库斯'] },
  { y: 453, mo: 3, t: '阿提拉之死', p: '蒂萨河', m: '今匈牙利大平原', ll: [20.2, 46.9], k: 'pol', refs: ['吉本·衰亡史', '约达尼斯'],
    d: '回到多瑙河北岸后，吉本写道，阿提拉**又娶了一位名叫伊尔迪科的美丽少女，加入他数不清的妻子之列||adding a beautiful maid, whose name was Ildico, to the list of his innumerable wives**。新婚之夜他喝得大醉，第二天早上，侍从们破门而入，发现他已经死了，鼻子大量出血，被自己的血呛死，新娘蒙着面纱坐在床边哭泣。匈人用刀割破自己的脸来哀悼他，把他葬在金、银、铁三层棺材里，埋葬的俘虏都被杀死。',
    who: ['阿提拉'] },
  { y: 454, mo: 6, t: '内达奥河之战', p: '内达奥河', m: '今潘诺尼亚某地，确切位置不明', ll: [19.0, 46.0], k: 'war', refs: ['吉本·衰亡史', '约达尼斯'],
    d: '阿提拉的众多儿子争夺遗产，要像分奴隶一样瓜分臣服的部族。格皮德王阿尔达里克率先起兵，东哥特人等纷纷响应。吉本写道：在潘诺尼亚的**内达河岸边一场血腥而决定性的战斗中||In a bloody and decisive conflict on the banks of the River Netad, in Pannonia**，格皮德人的长矛、哥特人的剑、匈人的箭交织在一起，三万匈人与盟军被杀，阿提拉的长子埃拉克战死。匈人帝国就此瓦解，格皮德人占据了达契亚，东哥特人作为东罗马的同盟者定居在潘诺尼亚，残余的匈人退回了黑海以北的草原。',
    who: ['阿尔达里克', '马尔西安'] },
  { y: 454, mo: 9, t: '埃提乌斯被杀', p: '拉文纳', m: '今意大利拉文纳', ll: [12.2, 44.42], k: 'pol', refs: ['吉本·衰亡史'],
    d: '匈人的威胁消失后，瓦伦提尼安三世不再需要埃提乌斯了。埃提乌斯想让儿子娶皇帝的女儿，宦官赫拉克利乌斯告诉皇帝他图谋篡位。九月二十一日，埃提乌斯进宫汇报财政，瓦伦提尼安突然拔剑，与侍从一起把这位统帅杀死在宫中。事后皇帝问一个罗马人自己做得好不好，那人回答：**陛下，我不知道您的动机或缘由，我只知道您就像一个用左手砍掉自己右手的人||I am ignorant, sir, of your motives or provocations; I only know, that you have acted like a man who cuts off his right hand with his left**（吉本语）。',
    who: ['埃提乌斯', '瓦伦提尼安三世'] },
  { y: 455, mo: 3, t: '瓦伦提尼安三世遇刺', p: '罗马', m: '今意大利罗马', ll: [12.48, 41.89], k: 'pol', refs: ['吉本·衰亡史'],
    d: '埃提乌斯有两个蛮族出身的卫士投入了皇帝的卫队，元老佩特罗尼乌斯·马克西穆斯怂恿他们为旧主报仇。三月十六日，**瓦伦提尼安在战神广场观看军事操练时，他们突然拔出武器冲上前去||Whilst Valentinian amused himself, in the field of Mars, with the spectacle of some military sports, they suddenly rushed upon him with drawn weapons**（吉本语），杀死了宦官赫拉克利乌斯，又刺死了皇帝，在场的大批随从无人阻拦。狄奥多西王朝在西部就此断绝。马克西穆斯自立为帝，强娶了先帝的遗孀欧多克西娅。',
    who: ['瓦伦提尼安三世'] },
  { y: 455, mo: 6, t: '汪达尔人洗劫罗马', p: '罗马', m: '今意大利罗马', ll: [12.48, 41.89], k: 'war', refs: ['吉本·衰亡史'],
    d: '据说是欧多克西娅暗中写信请盖萨里克来报仇。五月汪达尔人的舰队驶入台伯河口，马克西穆斯在逃跑时被愤怒的市民用石头砸死。六月二日盖萨里克进城，教宗利奥出城相迎，只求他不要杀人放火。汪达尔人在城中从容劫掠了十四天，吉本写道：**金银达数千塔兰特，连黄铜和红铜也被费力地搬走了||the gold and silver amounted to several thousand talents; yet even the brass and copper were laboriously removed**，朱庇特神庙屋顶的镀金铜瓦被揭走，提图斯从耶路撒冷圣殿掠来的器物也被运往迦太基，欧多克西娅与两个女儿被带走做人质。后世的“汪达尔主义”一词即来自这次劫掠。',
    who: ['盖萨里克', '教宗利奥'] },
  { y: 456, mo: 10, t: '西哥特人击败苏维汇人', p: '阿斯图里卡', m: '今西班牙莱昂省阿斯托加', ll: [-6.06, 42.46], k: 'war', refs: ['吉本·衰亡史', '后世文献'],
    d: '西哥特王狄奥多里克二世拥立了高卢元老阿维图斯为皇帝，又以罗马的名义出兵西班牙，十月在阿斯托加附近的奥尔维戈河边大败苏维汇人，俘杀了苏维汇王雷基阿尔，西哥特人的势力从此深入西班牙。同月，阿维图斯在意大利被将军李希梅尔与马约里安废黜。',
    who: ['狄奥多里克二世', '李希梅尔', '马约里安'] },
  { y: 457, mo: 2, t: '利奥一世即位', p: '君士坦丁堡', m: '今土耳其伊斯坦布尔', ll: [28.98, 41.01], k: 'pol', refs: ['吉本·衰亡史'],
    d: '马尔西安病逝，东部掌握兵权的阿兰人将军阿斯帕因为信奉阿里乌派，自己不能当皇帝，就扶立了自己的部下、色雷斯人利奥为帝。利奥一世据说是第一位由君士坦丁堡主教加冕的皇帝。他后来招募伊苏里亚山民组成新的卫队，用以抗衡日耳曼人将领，并在 471 年杀死了阿斯帕。',
    who: ['马尔西安', '利奥一世'] },
  { y: 457, mo: 4, t: '马约里安即位', p: '拉文纳', m: '今意大利拉文纳', ll: [12.2, 44.42], k: 'pol', refs: ['吉本·衰亡史'],
    d: '废黜阿维图斯之后，苏维汇人与西哥特人混血的李希梅尔出身蛮族，不能称帝，就把皇位交给了自己的战友马约里安。吉本对这位皇帝评价很高，说他颁布法令保护古迹，减轻税负，整顿官吏，努力恢复罗马的旧观。马约里安先在坎帕尼亚打退了汪达尔人的登陆，随后率军进入高卢，迫使西哥特人与勃艮第人重新承认罗马的权威。',
    who: ['马约里安', '李希梅尔'] },
  { y: 461, mo: 8, t: '马约里安被杀', p: '德尔托纳', m: '今意大利皮埃蒙特大区托尔托纳', ll: [8.86, 44.9], k: 'pol', refs: ['吉本·衰亡史'],
    d: '马约里安在西班牙东南的卡塔赫纳集结了三百艘战船，准备渡海收复阿非利加，盖萨里克收买了内奸，突袭焚毁了大部分船只。马约里安回到意大利，在托尔托纳被李希梅尔逮捕，剥去紫袍，五天后被处死。此后李希梅尔接连扶立了几个傀儡皇帝。马约里安在高卢的部将埃吉迪乌斯拒绝承认李希梅尔的皇帝，吉本说他**宣布对杀害他敬爱的主人的凶手永不宽恕||proclaimed his immortal resentment against the assassins of his beloved master**，在北高卢自立，以苏瓦松为中心，这个罗马人的孤岛又存在了二十五年。',
    who: ['马约里安', '李希梅尔', '埃吉迪乌斯'] },
  { y: 463, mo: 6, t: '希尔德里克与图尔奈', p: '图尔纳库姆', m: '今比利时图尔奈', ll: [3.39, 50.61], k: 'war', refs: ['后世文献', '考古'],
    d: '萨利法兰克人从莱茵河口南下，在图尔奈一带定居。他们的国王希尔德里克，据说是传说中的墨洛维的儿子，墨洛温王朝即以墨洛维命名。463 年他作为罗马的同盟者，与埃吉迪乌斯一起在奥尔良打败了西哥特人。1653 年人们在图尔奈发现了他的墓，出土了刻着“希尔德里克王”的图章戒指、三百多只镶金的蝉形饰物与一百多枚罗马金币，他的儿子就是后来统一高卢的克洛维。',
    who: ['希尔德里克', '埃吉迪乌斯'] },
  { y: 468, mo: 6, t: '邦角之役', p: '邦角', m: '今突尼斯纳布勒省', ll: [11.04, 37.08], k: 'war', refs: ['吉本·衰亡史'],
    d: '东西罗马联手发动了对汪达尔人的最大一次远征，利奥一世花费了十几万磅黄金，组织了一千一百艘船与十万大军，由皇后的弟弟巴西利斯库斯统率，**在邦角登陆，离迦太基约四十英里||He landed his troops at Cape Bona, or the promontory of Mercury, about forty miles from Carthage**（吉本语）。盖萨里克请求休战五天，巴西利斯库斯答应了。夜里风向一转，汪达尔人放出火船冲进罗马舰队，**罗马人一面忙着摆脱火船，一面被盖萨里克的战舰攻击||Whilst they labored to extricate themselves from the fire-ships, and to save at least a part of the navy, the galleys of Genseric assaulted them**（吉本语），远征全军覆没，东罗马的国库几乎被掏空，西罗马收复阿非利加的最后希望从此破灭。',
    who: ['利奥一世', '盖萨里克'] },
  { y: 474, mo: 1, t: '芝诺即位', p: '君士坦丁堡', m: '今土耳其伊斯坦布尔', ll: [28.98, 41.01], k: 'pol', refs: ['吉本·衰亡史'],
    d: '利奥一世病逝，外孙利奥二世继位，不到一年也死了，帝位传给了他的父亲、伊苏里亚山民出身的将军芝诺。芝诺的统治动荡不安，一度被巴西利斯库斯赶下台，又靠着东哥特人复位。同一年，西部的李希梅尔已死，东部扶立的西部皇帝尤利乌斯·奈波斯在拉文纳即位。',
    who: ['利奥一世', '芝诺'] },
  { y: 475, mo: 7, t: '欧里克的扩张', p: '托洛萨', m: '今法国图卢兹', ll: [1.44, 43.6], k: 'war', refs: ['吉本·衰亡史'],
    d: '466 年，欧里克杀死哥哥狄奥多里克二世，成为西哥特国王。吉本说，**在欧里克统治时期，消灭罗马帝国在西班牙与高卢的势力的计划被提出，并且几乎完成了||the design of extinguishing the Roman empire in Spain and Gaul was conceived, and almost completed, in the reign of Euric**。他越过比利牛斯山，攻下萨拉戈萨与潘普洛纳，征服了西班牙的大部分；在高卢，他与坚守奥弗涅的克莱蒙主教、诗人西多尼乌斯·阿波利纳里斯打了四年仗。475 年皇帝奈波斯把奥弗涅割给了他，西哥特王国从卢瓦尔河一直延伸到直布罗陀海峡。他还为臣民编写了第一部成文的哥特法典。同年，勃艮第人据有了里昂。',
    who: ['欧里克'] },
  { y: 475, mo: 10, t: '罗慕路斯·奥古斯都路斯即位', p: '拉文纳', m: '今意大利拉文纳', ll: [12.2, 44.42], k: 'pol', refs: ['吉本·衰亡史'],
    d: '奈波斯派曾在阿提拉手下做书记的潘诺尼亚人欧瑞斯特斯统领意大利的军队，欧瑞斯特斯却带兵进攻拉文纳，奈波斯逃回了达尔马提亚。欧瑞斯特斯自己没有称帝，而是在十月三十一日立了大约十四岁的儿子罗慕路斯为帝。这个少年的名字合起了罗马的建城者与第一位皇帝，人们却叫他“奥古斯都路斯”，意思是“小奥古斯都”。',
    who: ['罗慕路斯·奥古斯都路斯'] },
  { y: 476, mo: 9, t: '奥多亚克废黜罗慕路斯', p: '拉文纳', m: '今意大利拉文纳', ll: [12.2, 44.42], k: 'pol', refs: ['吉本·衰亡史'],
    d: '意大利的蛮族雇佣军要求像其他地方的同盟者那样分得三分之一的土地，欧瑞斯特斯拒绝了，他们就推举斯基里人首领奥多亚克为王，八月在帕维亚杀死欧瑞斯特斯。吉本写道：**孤立无援的奥古斯都路斯再也不能令人敬畏，只得乞求奥多亚克的宽恕||the helpless Augustulus, who could no longer command the respect, was reduced to implore the clemency, of Odoacer**。奥多亚克没有杀他，给了他一笔年金，让他住在那不勒斯湾的卢库鲁斯别墅。元老院奉命把皇帝的冠冕与紫袍送往君士坦丁堡，说西部不再需要单独的皇帝。奥多亚克以芝诺的名义统治意大利，后世把这一年当作西罗马帝国的终结。吉本在评论罗马衰亡时说：**与其追问罗马帝国为什么灭亡，我们更该惊讶它竟能存在这么久||instead of inquiring why the Roman empire was destroyed, we should rather be surprised that it had subsisted so long**。',
    who: ['奥多亚克', '罗慕路斯·奥古斯都路斯', '芝诺'] },
];

const PEOPLE_RAW = [
  // 西部的皇帝与罗马人
  ['约维安', 'rome', '', '', ''],
  ['瓦伦提尼安一世', 'rome', 'Flavius Valentinianus', '321–375', '潘诺尼亚基巴莱人，绳匠出身的将军老格拉提安之子。在尤利安与约维安手下任禁卫军官，364 年在尼西亚被推举为帝，立弟弟瓦伦斯统治东方，自己坐镇特里尔与米兰，加固莱茵河与多瑙河的防线，屡败阿勒曼尼人。他性情暴躁严酷，据说在寝宫旁养着两头吃人的母熊；宗教上宽容，不偏袒任何一派。375 年在接见夸狄人使者时盛怒中风而死。'],
  ['格拉提安', 'rome', 'Flavius Gratianus', '359–383', '瓦伦提尼安一世的长子，八岁即被立为奥古斯都，老师是诗人奥索尼乌斯。父亲死后统治西部，378 年在阿尔萨斯大败阿勒曼尼人，赶去增援瓦伦斯时阿德里安堡之战已经结束。次年立狄奥多西为东方的皇帝。他受安布罗斯影响，放弃“大祭司长”的称号，移走元老院的胜利女神祭坛。383 年马克西穆斯起兵，他的军队倒戈，在里昂被杀。'],
  ['瓦伦提尼安二世', 'rome', 'Flavius Valentinianus', '371–392', '瓦伦提尼安一世与尤斯提娜之子，四岁时被军队拥立为帝，名义上与哥哥格拉提安共治西部，实际只统治意大利、伊利里库姆与阿非利加。387 年被马克西穆斯赶出意大利，由狄奥多西护送复位，后被派到高卢，受法兰克将军阿博加斯特控制。392 年被发现吊死在维埃纳的宫中，年仅二十一岁。'],
  ['阿博加斯特', 'rome', 'Arbogastes', '?–394', '法兰克人出身的罗马将领，随狄奥多西讨伐马克西穆斯，后来以军队长官的身份辅佐瓦伦提尼安二世，实际掌握了西部。皇帝死后，他立尤吉尼乌斯为帝，支持元老院中的异教派。394 年在冷河之战中战败，两天后自杀。'],
  ['尤吉尼乌斯', 'rome', 'Flavius Eugenius', '?–394', '罗马的修辞学教师，在宫廷任书记官，由阿博加斯特在 392 年立为西部皇帝。他本人是基督徒，却允许异教徒恢复胜利女神的祭坛与古老的祭仪，旗帜上画着赫拉克勒斯的像。394 年在冷河之战中被狄奥多西俘获斩首，这是异教在罗马最后一次的公开抵抗。'],
  ['安布罗斯', 'rome', 'Ambrose of Milan', '约339–397', '高卢禁卫军长官之子，生于特里尔，在罗马受教育，任利古里亚与埃米利亚的总督。374 年被米兰人拥立为主教。他反对阿里乌派与异教，迫使瓦伦提尼安二世拒绝恢复胜利女神祭坛，又使狄奥多西为帖撒罗尼迦屠杀公开忏悔，确立了“皇帝在教会之内，而不在教会之上”的原则。他为奥古斯丁施洗，创作的赞美诗在西方教会传唱至今，是拉丁教会的四大博士之一。'],
  ['达马苏斯', 'rome', 'Pope Damasus I', '约305–384', '罗马的主教，366 年在与乌尔西努斯的血腥竞争中胜出，在位十八年。他确立了罗马主教的首席地位，以“使徒之座”称呼罗马教会；委托秘书哲罗姆修订拉丁文圣经；修整殉道者的地下墓穴，亲自撰写铭文，由书法家刻成精美的字体。'],
  ['哲罗姆', 'rome', 'Jerome (Eusebius Sophronius Hieronymus)', '约347–420', '达尔马提亚边境斯特里多人，在罗马受教育，曾在叙利亚的沙漠中隐修并学习希伯来文。382 年任教宗达马苏斯的秘书，开始修订拉丁文圣经。后来定居伯利恒，用二十多年从希伯来文与希腊文直接译出全部圣经，即后来西方教会通用的“武加大译本”。他文笔犀利，好与人论战，是拉丁教会的四大博士之一。'],
  ['叙马库斯', 'rome', 'Quintus Aurelius Symmachus', '约345–402', '罗马贵族，著名的演说家，384 年任罗马城长官，391 年任执政官。他是元老院中异教派的领袖，384 年上书请求恢复胜利女神的祭坛，与安布罗斯的辩论流传至今。他推荐年轻的奥古斯丁去米兰任修辞学教授。他留下的十卷书信是了解罗马末期贵族生活的重要史料。'],
  ['奥古斯丁', 'rome', 'Augustine of Hippo (Aurelius Augustinus)', '354–430', '阿非利加塔加斯特人，父亲是异教徒，母亲莫妮卡是虔诚的基督徒。在迦太基读书，信奉摩尼教九年，先后在迦太基、罗马与米兰教授修辞学。386 年在米兰皈依，次年由安布罗斯施洗，回到阿非利加，395 年任希波主教，直到去世。他的《忏悔录》是西方第一部内省的自传，《上帝之城》为罗马陷落后的基督教辩护。他关于原罪、恩典、三位一体与正义战争的思想影响了整个西方神学，是拉丁教会的四大博士之一。430 年死于被汪达尔人围困的希波城中。'],
  ['图尔的马丁', 'rome', 'Martin of Tours', '约316–397', '潘诺尼亚萨瓦里亚人，军官之子，年轻时在罗马骑兵中服役。传说他在亚眠城门把半件斗篷送给乞丐。退伍后追随普瓦捷主教希拉里，在利居热建立了高卢第一座修道院，371 年被拥立为图尔主教，在乡间传教，捣毁神庙。他是最早不是殉道者而被尊为圣徒的人之一，后来成为法兰克王国的守护圣徒。'],
  ['霍诺留', 'rome', 'Flavius Honorius', '384–423', '狄奥多西的次子，393 年被立为奥古斯都，395 年十岁时继承西部，由斯提里科辅政，娶了斯提里科的两个女儿。402 年把宫廷迁到拉文纳。408 年处死斯提里科后，他无力对付阿拉里克，坐视罗马在 410 年被攻陷，又失去了不列颠，任由蛮族在高卢与西班牙定居。在位二十八年，最终病逝于拉文纳。'],
  ['斯提里科', 'rome', 'Flavius Stilicho', '约359–408', '汪达尔人军官与罗马母亲之子，狄奥多西的大将，娶了皇帝的侄女与养女塞丽娜。狄奥多西死后，他以霍诺留监护人的身份掌握西部十三年，先后在希腊、波伦提亚与维罗纳挡住了阿拉里克，406 年在费苏莱歼灭拉达盖苏斯的大军，诗人克劳狄安为他写了许多颂诗。408 年被政敌诬陷图谋篡位，在拉文纳被斩首。'],
  ['忒勒马科斯', 'rome', 'Telemachus', '?–404', '据教会史家狄奥多勒记载，是一位来自东方的修士。404 年在罗马竞技场的角斗表演中跳进场内，想把角斗士分开，被观众用石头砸死。霍诺留随后下令废除角斗，他被尊为圣徒。'],
  ['加拉·普拉西提阿', 'rome', 'Aelia Galla Placidia', '约390–450', '狄奥多西与第二位妻子加拉的女儿，霍诺留同父异母的妹妹。410 年罗马陷落时被阿拉里克掳走，414 年在纳博讷嫁给西哥特王阿陶尔夫，丈夫被杀后被送回罗马，417 年被迫嫁给将军君士坦提乌斯，生下瓦伦提尼安三世。与霍诺留失和后流亡君士坦丁堡，425 年随东部军队回来，以太后身份摄政十二年。她在拉文纳的陵墓至今保存着五世纪精美的镶嵌画。'],
  ['瓦伦提尼安三世', 'rome', 'Flavius Placidius Valentinianus', '419–455', '加拉·普拉西提阿与君士坦提乌斯三世之子，六岁时由东部的狄奥多西二世立为西部皇帝，先后由母亲与埃提乌斯掌权。他在位三十年间，汪达尔人夺走了阿非利加，阿提拉蹂躏了高卢与意大利。454 年亲手杀死埃提乌斯，次年在罗马被埃提乌斯的旧部刺杀，狄奥多西王朝在西部断绝。'],
  ['埃提乌斯', 'rome', 'Flavius Aetius', '约391–454', '多瑙河边的杜罗斯托鲁姆人，骑兵长官高登提乌斯之子，少年时先后在阿拉里克与匈人那里做人质，与匈人结下深交。433 年起任西部最高统帅，二十年间在高卢周旋于西哥特人、法兰克人、勃艮第人与巴高达起义军之间，三任执政官。451 年联合西哥特人在卡塔劳尼平原挡住了阿提拉，被称为“最后的罗马人”。454 年被瓦伦提尼安三世亲手杀死。'],
  ['卜尼法斯', 'rome', 'Bonifacius', '?–432', '色雷斯出身的罗马将军，阿非利加伯爵，奥古斯丁的朋友，以勇武与公正著称，413 年在马赛击退过阿陶尔夫。他与宫廷不和，被指控谋反，后世传说是他请汪达尔人进入阿非利加。他死守希波十四个月，431 年战败回到意大利，432 年在拉文纳附近与埃提乌斯交战，获胜后伤重而死。'],
  ['教宗利奥', 'rome', 'Pope Leo I', '约400–461', '罗马主教，440 年至 461 年在位，后世称“大利奥”。他确立了罗马主教继承彼得、统领全教会的理论；451 年他论基督二性的书信被卡尔西顿会议采纳。452 年出城劝说阿提拉退兵，455 年说服盖萨里克在洗劫罗马时不杀人放火。他是第一位被称为“大”的教宗。'],
  ['李希梅尔', 'rome', 'Flavius Ricimer', '约418–472', '父亲是苏维汇人的王子，母亲是西哥特王瓦利亚的女儿。他在埃提乌斯手下作战，456 年废黜阿维图斯，此后十六年间以“贵人”的身份操纵西部的朝政，先后扶立、废黜了马约里安、利比乌斯·塞维鲁、安特米乌斯与奥利布里乌斯四位皇帝。472 年他攻入罗马，杀死安特米乌斯，几周后病死。'],
  ['马约里安', 'rome', 'Flavius Julius Valerius Majorianus', '约420–461', '出身罗马军人世家，在埃提乌斯手下作战。457 年由李希梅尔扶立为西部皇帝。他颁布法令减轻税负，禁止拆毁罗马的古建筑，率军击败汪达尔人与西哥特人，迫使高卢重新服从。460 年在西班牙集结舰队准备收复阿非利加，被汪达尔人焚毁，次年被李希梅尔废黜处死。吉本称他为罗马衰亡中“一个伟大而英勇的人物”。'],
  ['罗慕路斯·奥古斯都路斯', 'rome', 'Romulus Augustulus', '约461–约507后', '潘诺尼亚人欧瑞斯特斯之子，母亲是一位罗马贵族的女儿。475 年十月，父亲赶走皇帝奈波斯，立他为西部皇帝。476 年八月欧瑞斯特斯被奥多亚克杀死，九月他在拉文纳被废，得到一笔年金，住在那不勒斯湾的卢库鲁斯别墅，此后的下落不明。他通常被当作西罗马帝国的最后一位皇帝。'],
  ['奥多亚克', 'rome', '', '', ''],
  ['阿米阿努斯·马塞利努斯', 'rome', '', '', ''],
  // 东部的皇帝
  ['瓦伦斯', 'east', 'Flavius Julius Valens', '328–378', '瓦伦提尼安一世的弟弟，364 年被哥哥立为东方的奥古斯都。他平定了普罗科匹乌斯的叛乱，与多瑙河北岸的哥特人打了三年仗，又同波斯争夺亚美尼亚。他信奉阿里乌派，迫害尼西亚派的主教。376 年允许逃避匈人的哥特人渡过多瑙河，结果引发大乱，378 年在阿德里安堡大败，战死或被烧死在农舍里，尸首始终没有找到。'],
  ['普罗科匹乌斯', 'east', 'Procopius', '326–366', '西里西亚人，尤利安母系的亲属，曾随尤利安东征。尤利安死后，传说尤利安曾把皇位留给他，他担心被约维安与瓦伦斯猜忌，躲藏了两年。365 年在君士坦丁堡称帝，打着君士坦丁家族的旗号，次年部下倒戈，被瓦伦斯斩首。'],
  ['狄奥多西', 'east', 'Flavius Theodosius', '347–395', '西班牙考卡人，名将老狄奥多西之子，随父亲在不列颠与阿非利加作战。父亲被冤杀后退隐故乡，379 年被格拉提安立为东方的皇帝。他与哥特人议和，让他们以同盟者身份定居帝国境内；宣布尼西亚信经为国教，召开君士坦丁堡会议，禁绝异教的祭祀；两次西征，打败马克西穆斯与尤吉尼乌斯，394 年成为最后一位统治整个罗马帝国的皇帝。帖撒罗尼迦屠杀后，他在安布罗斯面前公开忏悔。后世称他为“狄奥多西大帝”。'],
  ['阿卡狄乌斯', 'east', 'Flavius Arcadius', '377–408', '狄奥多西的长子，383 年被立为奥古斯都，395 年继承东部。他性格懦弱，朝政先后被禁卫军长官鲁菲努斯、宦官欧特罗皮乌斯与皇后欧多克西娅把持，哥特将领盖纳斯一度占据君士坦丁堡。他流放了君士坦丁堡主教约翰·克里索斯托。408 年病逝，年仅三十一岁。'],
  ['约翰·克里索斯托', 'east', 'John Chrysostom', '约347–407', '安条克人，师从修辞学家利巴尼乌斯，因讲道雄辩被称为“金口”。398 年被召为君士坦丁堡主教，严厉批评宫廷与贵族的奢侈，得罪了皇后欧多克西娅与亚历山大里亚主教提奥菲卢斯，两次被流放，407 年死在流放途中。他留下的讲道词数量极多，是希腊教会最受尊敬的教父之一。'],
  ['狄奥多西二世', 'east', 'Flavius Theodosius', '401–450', '阿卡狄乌斯之子，出生几个月就被立为奥古斯都，七岁继位，在位四十二年，是在位最久的罗马皇帝之一。他性情温和，好读书，以书法闻名，号称“书法家”，朝政长期由姐姐普尔喀丽娅与大臣主持。在位期间修建了君士坦丁堡的狄奥多西城墙，创立了君士坦丁堡的高等学府，颁行《狄奥多西法典》，召开以弗所会议；却多次向阿提拉纳贡求和。450 年坠马而死。'],
  ['普尔喀丽娅', 'east', 'Aelia Pulcheria', '399–453', '阿卡狄乌斯的长女，十五岁时立誓守贞，带着两个妹妹过着修道般的生活，次年被尊为奥古斯塔，主持弟弟狄奥多西二世的宫廷。她为弟弟选定了雅典哲学家的女儿欧多基娅为后。弟弟死后，她嫁给马尔西安，使他成为皇帝，主持召开了卡尔西顿会议。她修建了多座供奉圣母的教堂，被东正教会尊为圣徒。'],
  ['希帕提娅', 'east', 'Hypatia', '约355/370–415', '亚历山大里亚的数学家与哲学家，数学家塞翁的女儿。她注释过丢番图的《算术》与阿波罗尼奥斯的《圆锥曲线论》，协助父亲编订托勒密的著作，讲授新柏拉图主义哲学，学生中有后来的主教叙涅修斯。她与埃及总督奥瑞斯特斯交好，被卷入总督与主教西里尔的冲突，415 年被一群基督徒暴徒残杀。她是古代最著名的女性学者。'],
  ['西里尔', 'east', 'Cyril of Alexandria', '约376–444', '亚历山大里亚主教提奥菲卢斯的外甥，412 年继任主教。他驱逐城中的犹太人，与总督奥瑞斯特斯争权，希帕提娅之死与他的追随者有关。431 年主持以弗所会议，宣布聂斯脱利为异端，确立了称马利亚为“神之母”的教义。他是一位重要的神学家，被东西方教会都尊为圣徒。'],
  ['聂斯脱利', 'east', 'Nestorius', '约386–约451', '叙利亚日耳曼尼基亚人，在安条克当修士，以讲道闻名，428 年被狄奥多西二世召为君士坦丁堡主教。他反对称马利亚为“神之母”，主张基督的神性与人性应当分开来说，被西里尔指为异端，431 年在以弗所会议上被革职，流放到埃及的沙漠中死去。他的追随者在波斯建立了东方教会，传教到中亚与中国，唐代称为景教。'],
  ['马尔西安', 'east', 'Flavius Marcianus', '约392–457', '色雷斯或伊利里亚的军人，在阿兰人将军阿斯帕手下任职。450 年狄奥多西二世死后，普尔喀丽娅与他名义上结婚，立他为帝。他拒绝向阿提拉纳贡，整顿财政，召开卡尔西顿会议。他在位期间东罗马得到了喘息，国库重新充实起来。'],
  ['普里斯库斯', 'east', 'Priscus of Panium', '约410/420–472后', '色雷斯帕尼翁人，东罗马的修辞学家与外交官。449 年随使团到阿提拉的王庭，详细记下了匈人的风俗、宴会与阿提拉本人的形象。他的八卷《历史》只有残篇传世，约达尼斯的《哥特史》大量引用了他的记载，是今天了解阿提拉最重要的史料。'],
  ['利奥一世', 'east', 'Leo I (Flavius Valerius Leo)', '约401–474', '色雷斯或达契亚出身的军官，457 年由阿兰人将军阿斯帕扶立为东罗马皇帝。他招募伊苏里亚人组成卫队，把女儿嫁给伊苏里亚首领芝诺，471 年杀死阿斯帕，摆脱了日耳曼将领的控制。468 年组织大舰队远征汪达尔人，在邦角惨败。后世称他为“大利奥”或“屠夫利奥”。'],
  ['芝诺', 'east', '', '', ''],
  // 西哥特人
  ['弗里提格恩', 'goths', 'Fritigern', '?–约380', '特尔温吉哥特人的首领，为了得到瓦伦斯的支持接受了阿里乌派的基督教。376 年率领逃避匈人的哥特人渡过多瑙河，因罗马官员的盘剥而起兵，378 年在阿德里安堡大败罗马军队，杀死了瓦伦斯。此后哥特人在巴尔干劫掠，约 380 年后他从史料中消失。'],
  ['乌尔菲拉', 'goths', '', '', ''],
  ['阿拉里克', 'goths', 'Alaric I', '约370–410', '多瑙河口佩乌切岛出生的哥特贵族，巴尔特家族的成员。394 年率哥特同盟军为狄奥多西作战，次年被哥特人拥立为王。他先后蹂躏希腊，两次进攻意大利，被斯提里科击退。斯提里科死后，他三次围困罗马，410 年八月攻陷罗马城，劫掠三天。同年年底在科森扎病死，哥特人把他葬在布森托河的河床下。'],
  ['阿陶尔夫', 'goths', 'Athaulf', '?–415', '阿拉里克的妻弟，410 年继任西哥特王，率部离开意大利进入高卢。414 年在纳博讷按罗马礼仪娶了加拉·普拉西提阿，据奥罗修斯记载，他曾说想用哥特人的力量来恢复罗马的威名。被罗马逼迫退入西班牙，415 年在巴塞罗那被手下刺杀。'],
  ['瓦利亚', 'goths', 'Wallia', '?–418', '西哥特王，415 年继位。他在西班牙南部渡海去阿非利加未成，与罗马讲和，归还了加拉·普拉西提阿，换取粮食，并以罗马同盟者的身份出兵西班牙，几乎消灭了西林汪达尔人与阿兰人。418 年罗马把阿基坦交给西哥特人定居，同年他病逝，西哥特王国由此建立。'],
  ['狄奥多里克一世', 'goths', 'Theodoric I', '?–451', '西哥特王，据说是阿拉里克的外孙，418 年继瓦利亚为王，以图卢兹为王都，统治三十三年。他多次进攻阿尔勒与纳博讷，被埃提乌斯击退，一个女儿嫁给了汪达尔王子，却被盖萨里克割去鼻子与耳朵送回。451 年与埃提乌斯联手抗击阿提拉，在卡塔劳尼平原战死。'],
  ['狄奥多里克二世', 'goths', 'Theodoric II', '约426–466', '狄奥多里克一世之子，453 年杀死哥哥托里斯蒙德继位。他与高卢的罗马贵族交好，455 年拥立阿维图斯为西部皇帝，次年以罗马的名义出兵西班牙，大败苏维汇人。诗人西多尼乌斯·阿波利纳里斯在书信中详细描写过他的宫廷生活。466 年被弟弟欧里克杀死。'],
  ['欧里克', 'goths', 'Euric', '约440–484', '狄奥多里克一世之子，466 年杀死哥哥狄奥多里克二世继位。他不再以罗马同盟者自居，征服了西班牙的大部分与高卢从卢瓦尔河到罗讷河的土地，475 年取得奥弗涅，476 年占领普罗旺斯，使西哥特王国成为西欧最强大的国家。他颁布了以拉丁文写成的《欧里克法典》。他信奉阿里乌派，对正统派的主教多有压制。'],
  // 匈人
  ['阿提拉', 'huns', 'Attila', '?–453', '匈人王蒙杜克之子，434 年与哥哥布列达继承叔父卢阿，445 年杀死布列达独揽大权，统治从莱茵河到黑海北岸的诸多部族，王庭设在多瑙河与蒂萨河之间的平原上。他屡次蹂躏巴尔干，迫使东罗马大量纳贡；451 年入侵高卢，在卡塔劳尼平原被埃提乌斯与西哥特人挡住；452 年入侵意大利，夷平阿奎莱亚，在教宗利奥劝说下退兵。453 年在新婚之夜死去。后世称他为“上帝之鞭”。'],
  // 汪达尔人
  ['盖萨里克', 'vandals', '', '', ''],
  // 诸国与诸部
  ['雷齐拉', 'suebi', 'Rechila', '?–448', '苏维汇王，438 年继承父亲赫尔梅里克。他趁汪达尔人渡海之机向南扩张，439 年占领梅里达，441 年攻占塞维利亚，使苏维汇王国在一个时期内据有西班牙的大半。448 年病死于梅里达，他的儿子雷基阿尔是第一位信奉正统基督教的日耳曼国王。'],
  ['阿尔达里克', 'gepids', 'Ardaric', '?–约460', '格皮德人的国王，阿提拉最信任的属臣之一，451 年随阿提拉进攻高卢。阿提拉死后，他率先起兵反抗阿提拉的儿子们，454 年在内达奥河大败匈人，格皮德人随后占据了达契亚与蒂萨河以东的土地。'],
  ['埃吉迪乌斯', 'soissons', 'Aegidius', '?–464/465', '高卢的罗马贵族，马约里安的战友，458 年任高卢的军队长官。马约里安被杀后，他拒绝承认李希梅尔扶立的皇帝，在北高卢自立，以苏瓦松为中心，据说萨利法兰克人一度推他为王。463 年在奥尔良击败西哥特人，464 年或 465 年去世，儿子西阿格里乌斯继续统治，486 年被克洛维灭亡。'],
  ['希尔德里克', 'franks', 'Childeric I', '约437–481', '萨利法兰克人的国王，据说是墨洛维之子，以图尔奈为中心，作为罗马的同盟者与埃吉迪乌斯一起对抗西哥特人与撒克逊人。1653 年人们在图尔奈发现了他的墓，出土了刻有其名的图章戒指与大批金饰，大部分在 1831 年被盗。他的儿子克洛维建立了法兰克王国。'],
  ['亨吉斯特', 'saxons', 'Hengist', '传说?–488', '传说中的朱特人首领，与兄弟霍萨应不列颠统治者沃蒂根之邀，带着三条船来不列颠抵御皮克特人，后来反目，夺取肯特，建立了肯特王国。他的故事见于比德的《英吉利教会史》与《盎格鲁—撒克逊编年史》，真实性难以确定。'],
  ['帕特里克', 'britons', 'Saint Patrick', '五世纪', '不列颠一个罗马化基督徒家庭的儿子，父亲是执事，也是地方议员。十六岁时被爱尔兰海盗掳去放羊六年，逃回家乡后成为教士，又回到爱尔兰传教，据说用三叶草讲解三位一体。他亲笔写的《忏悔》与《致科罗提库斯书》流传至今，是五世纪不列颠罕见的第一手文献。他被尊为爱尔兰的守护圣徒。'],
  ['马克西穆斯', 'maximus', 'Magnus Maximus', '约335–388', '西班牙人，老狄奥多西的旧部，在不列颠任军职。383 年被不列颠的军队拥立为帝，渡海杀死格拉提安，据有不列颠、高卢与西班牙，以特里尔为都。他是正统派基督徒，385 年处死了被控为异端的主教普里西利安，这是第一次有基督徒因异端罪被国家处死。387 年进攻意大利，次年被狄奥多西击败处死。在威尔士的传说中，他是许多王族的祖先。'],
  ['沙普尔二世', 'persia', '', '', ''],
];
